import json
G=load()
def transform(g):
    h,w=len(g),len(g[0])
    fullrows={r for r in range(h) if len(set(g[r]))==1}
    fullcols={c for c in range(w) if len({g[r][c] for r in range(h)})==1}
    return [[2 if (r in fullrows or c in fullcols) else g[r][c] for c in range(w)] for r in range(h)]
